/**
 * All constant values for the CTRE Phoenix 6 swerve drivetrain.
 *
 * <p>These values came from the Tuner X swerve generator (2026 export). Hardware-calibrated
 * values (CAN IDs, encoder offsets, gear ratios, PID gains) are from the physical robot scan.
 *
 * <p>Assumes a standard CTRE "Swerve X2" chassis with:
 * <ul>
 *   <li>4 × Kraken X60 drive motors (TalonFX)
 *   <li>4 × Kraken X60 steer motors (TalonFX)
 *   <li>4 × CANcoder absolute encoders
 *   <li>Pigeon 2.0 IMU (used for fast odometry, but heading is overridden by QuestNav)
 *   <li>All on the "CAN FD" CANivore bus
 * </ul>
 */
public class TunerConstants {

  // ─── Steer Motor PID / Feed-Forward ────────────────────────────────────────

  private static final Slot0Configs steerGains = new Slot0Configs()
      .withKP(100).withKI(0).withKD(0.5)
      .withKS(0.1).withKV(2.49).withKA(0)
      .withStaticFeedforwardSign(StaticFeedforwardSignValue.UseClosedLoopSign);

  // ─── Drive Motor PID / Feed-Forward ────────────────────────────────────────

  private static final Slot0Configs driveGains = new Slot0Configs()
      .withKP(0.1).withKI(0).withKD(0)
      .withKS(0).withKV(0.124);

  // ─── Closed-Loop Output Type ───────────────────────────────────────────────

  private static final ClosedLoopOutputType kSteerClosedLoopOutput = ClosedLoopOutputType.Voltage;
  private static final ClosedLoopOutputType kDriveClosedLoopOutput = ClosedLoopOutputType.Voltage;

  // ─── Motor Type ────────────────────────────────────────────────────────────

  private static final DriveMotorArrangement kDriveMotorType = DriveMotorArrangement.TalonFX_Integrated;
  private static final SteerMotorArrangement kSteerMotorType = SteerMotorArrangement.TalonFX_Integrated;

  // ─── Feedback Source ───────────────────────────────────────────────────────

  private static final SteerFeedbackType kSteerFeedbackType = SteerFeedbackType.FusedCANcoder;

  // ─── Current Limits ────────────────────────────────────────────────────────

  private static final Current kSlipCurrent = Amps.of(120);

  // ─── Initial Configs ───────────────────────────────────────────────────────

  private static final TalonFXConfiguration driveInitialConfigs = new TalonFXConfiguration();
  private static final TalonFXConfiguration steerInitialConfigs = new TalonFXConfiguration()
      .withCurrentLimits(
          new CurrentLimitsConfigs()
              .withStatorCurrentLimit(Amps.of(60))
              .withStatorCurrentLimitEnable(true));
  private static final CANcoderConfiguration encoderInitialConfigs = new CANcoderConfiguration();
  private static final Pigeon2Configuration pigeonConfigs = null;

  // ─── CAN Bus ───────────────────────────────────────────────────────────────

  public static final CANBus kCANBus = new CANBus("CAN FD", "./logs/example.hoot");

  // ─── Speed ─────────────────────────────────────────────────────────────────

  public static final LinearVelocity kSpeedAt12Volts = MetersPerSecond.of(4.39);

  // ─── Gear Ratios / Wheel ───────────────────────────────────────────────────

  private static final double kCoupleRatio = 4.5;
  private static final double kDriveGearRatio = 7.03125;
  private static final double kSteerGearRatio = 26.09090909090909;
  private static final Distance kWheelRadius = Inches.of(2);

  /** Convenience constant for subsystems that need wheel radius in meters. */
  public static final double kWheelRadiusMeters = kWheelRadius.in(Meters);

  // ─── Drive Motor Inversion ─────────────────────────────────────────────────

  private static final boolean kInvertLeftSide = false;
  private static final boolean kInvertRightSide = true;

  // ─── Pigeon 2 ──────────────────────────────────────────────────────────────

  /**
   * CAN ID of the Pigeon 2.0 IMU on the CANivore bus.
   *
   * <p>Note: The Pigeon is still used by CTRE's high-frequency odometry loop for smooth wheel
   * odometry integration. QuestNav overrides the heading at the pose-estimator level by feeding
   * vision measurements with very tight standard deviations.
   */
  private static final int kPigeonId = 30;

  // ─── Simulation ────────────────────────────────────────────────────────────

  private static final MomentOfInertia kSteerInertia = KilogramSquareMeters.of(0.01);
  private static final MomentOfInertia kDriveInertia = KilogramSquareMeters.of(0.01);
  private static final Voltage kSteerFrictionVoltage = Volts.of(0.2);
  private static final Voltage kDriveFrictionVoltage = Volts.of(0.2);

  // ─── Odometry Standard Deviations ─────────────────────────────────────────

  /**
   * Wheel odometry standard deviations [X m, Y m, θ rad]. These represent how much we trust the
   * wheel/Pigeon odometry between QuestNav updates.
   */
  public static final Matrix<N3, N1> kOdometryStdDevs = VecBuilder.fill(0.1, 0.1, 0.1);

  /**
   * Vision (QuestNav) standard deviations [X m, Y m, θ rad]. Very low values make QuestNav the
   * dominant source of heading and position data.
   *
   * <p>These are duplicated in Constants.QuestNavConstants for clarity; if you change one, change
   * the other.
   */
  public static final Matrix<N3, N1> kVisionStdDevs = VecBuilder.fill(0.02, 0.02, 0.035);

  // ─── Drivetrain Constants ──────────────────────────────────────────────────

  public static final SwerveDrivetrainConstants DrivetrainConstants =
      new SwerveDrivetrainConstants()
          .withCANBusName(kCANBus.getName())
          .withPigeon2Id(kPigeonId)
          .withPigeon2Configs(pigeonConfigs);

  // ─── Module Constants Factory ──────────────────────────────────────────────

  private static final SwerveModuleConstantsFactory<
      TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration> ConstantCreator =
      new SwerveModuleConstantsFactory<
          TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration>()
          .withDriveMotorGearRatio(kDriveGearRatio)
          .withSteerMotorGearRatio(kSteerGearRatio)
          .withCouplingGearRatio(kCoupleRatio)
          .withWheelRadius(kWheelRadius)
          .withSteerMotorGains(steerGains)
          .withDriveMotorGains(driveGains)
          .withSteerMotorClosedLoopOutput(kSteerClosedLoopOutput)
          .withDriveMotorClosedLoopOutput(kDriveClosedLoopOutput)
          .withSlipCurrent(kSlipCurrent)
          .withSpeedAt12Volts(kSpeedAt12Volts)
          .withDriveMotorType(kDriveMotorType)
          .withSteerMotorType(kSteerMotorType)
          .withFeedbackSource(kSteerFeedbackType)
          .withDriveMotorInitialConfigs(driveInitialConfigs)
          .withSteerMotorInitialConfigs(steerInitialConfigs)
          .withEncoderInitialConfigs(encoderInitialConfigs)
          .withSteerInertia(kSteerInertia)
          .withDriveInertia(kDriveInertia)
          .withSteerFrictionVoltage(kSteerFrictionVoltage)
          .withDriveFrictionVoltage(kDriveFrictionVoltage);

  // ─── Per-Module Constants ──────────────────────────────────────────────────

  // Front Left
  private static final int kFrontLeftDriveMotorId = 11;
  private static final int kFrontLeftSteerMotorId = 10;
  private static final int kFrontLeftEncoderId = 12;
  private static final Angle kFrontLeftEncoderOffset = Rotations.of(0.008056640625);
  private static final boolean kFrontLeftSteerMotorInverted = false;
  private static final boolean kFrontLeftEncoderInverted = false;

  private static final Distance kFrontLeftXPos = Inches.of(10.875);
  private static final Distance kFrontLeftYPos = Inches.of(10.875);

  // Front Right
  private static final int kFrontRightDriveMotorId = 5;
  private static final int kFrontRightSteerMotorId = 4;
  private static final int kFrontRightEncoderId = 6;
  private static final Angle kFrontRightEncoderOffset = Rotations.of(0.2119140625);
  private static final boolean kFrontRightSteerMotorInverted = false;
  private static final boolean kFrontRightEncoderInverted = false;

  private static final Distance kFrontRightXPos = Inches.of(10.875);
  private static final Distance kFrontRightYPos = Inches.of(-10.875);

  // Back Left
  private static final int kBackLeftDriveMotorId = 2;
  private static final int kBackLeftSteerMotorId = 1;
  private static final int kBackLeftEncoderId = 3;
  private static final Angle kBackLeftEncoderOffset = Rotations.of(-0.21826171875);
  private static final boolean kBackLeftSteerMotorInverted = false;
  private static final boolean kBackLeftEncoderInverted = false;

  private static final Distance kBackLeftXPos = Inches.of(-10.875);
  private static final Distance kBackLeftYPos = Inches.of(10.875);

  // Back Right
  private static final int kBackRightDriveMotorId = 8;
  private static final int kBackRightSteerMotorId = 7;
  private static final int kBackRightEncoderId = 9;
  private static final Angle kBackRightEncoderOffset = Rotations.of(-0.49951171875);
  private static final boolean kBackRightSteerMotorInverted = false;
  private static final boolean kBackRightEncoderInverted = false;

  private static final Distance kBackRightXPos = Inches.of(-10.875);
  private static final Distance kBackRightYPos = Inches.of(-10.875);

  // ─── Module Instances ──────────────────────────────────────────────────────

  public static final SwerveModuleConstants<
      TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration> FrontLeft =
      ConstantCreator.createModuleConstants(
          kFrontLeftSteerMotorId, kFrontLeftDriveMotorId, kFrontLeftEncoderId,
          kFrontLeftEncoderOffset, kFrontLeftXPos, kFrontLeftYPos,
          kInvertLeftSide, kFrontLeftSteerMotorInverted, kFrontLeftEncoderInverted);

  public static final SwerveModuleConstants<
      TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration> FrontRight =
      ConstantCreator.createModuleConstants(
          kFrontRightSteerMotorId, kFrontRightDriveMotorId, kFrontRightEncoderId,
          kFrontRightEncoderOffset, kFrontRightXPos, kFrontRightYPos,
          kInvertRightSide, kFrontRightSteerMotorInverted, kFrontRightEncoderInverted);

  public static final SwerveModuleConstants<
      TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration> BackLeft =
      ConstantCreator.createModuleConstants(
          kBackLeftSteerMotorId, kBackLeftDriveMotorId, kBackLeftEncoderId,
          kBackLeftEncoderOffset, kBackLeftXPos, kBackLeftYPos,
          kInvertLeftSide, kBackLeftSteerMotorInverted, kBackLeftEncoderInverted);

  public static final SwerveModuleConstants<
      TalonFXConfiguration, TalonFXConfiguration, CANcoderConfiguration> BackRight =
      ConstantCreator.createModuleConstants(
          kBackRightSteerMotorId, kBackRightDriveMotorId, kBackRightEncoderId,
          kBackRightEncoderOffset, kBackRightXPos, kBackRightYPos,
          kInvertRightSide, kBackRightSteerMotorInverted, kBackRightEncoderInverted);

  // ─── Drivetrain Factory ────────────────────────────────────────────────────

  /**
   * Factory method that creates the {@link DrivetrainSubsystem} with all four modules and the
   * QuestNav-aware vision standard deviations.
   *
   * <p>Call this once in {@code RobotContainer} and store the result.
   */
  public static DrivetrainSubsystem createDrivetrain() {
    return new DrivetrainSubsystem(
        DrivetrainConstants,
        250.0, // Odometry thread frequency (Hz) – 250 Hz on CAN FD
        kOdometryStdDevs,
        kVisionStdDevs,
        FrontLeft,
        FrontRight,
        BackLeft,
        BackRight);
  }
}
